"""Archive independent peer source admission, including every failed control."""

import hashlib
import json
import subprocess
from datetime import datetime, timezone
from pathlib import Path

import docker

from serena_sources import snapshot

ROOT = Path(__file__).parent
CHECKOUT = Path('/home/zhongming/CodeNib-codegraph-benefit')
OUT = CHECKOUT / 'docs/experiments'
BASE = 'bc62135bde6577c695a198434853556c191b2461'
SELECTED = {
    'requests': {'serena': 'serena-requests1', 'codegraph': 'codegraph-requests2', 'task': 'psf__requests-1921-lookup', 'symbol': 'Session/prepare_request'},
    'flask': {'serena': 'serena-flask2', 'codegraph': 'codegraph-flask3', 'task': 'pallets__flask-5014-lookup', 'symbol': 'Flask/process_response'},
    'pytest': {'serena': 'serena-pytest3', 'codegraph': 'codegraph-pytest1', 'task': 'pytest-dev__pytest-5809-lookup', 'symbol': 'CallInfo/from_call'},
}
CLASSIFICATION = {
    'serena-pytest1': 'Preparation configuration failure: uv attempts a PyPI lookup despite cached Pyright, and network-none prevents DNS. Explicit Python selection already avoids the original Pascal prompt. No claim of an intrinsic Serena indexing failure.',
    'serena-pytest2': 'Controller mapping failure: the returned LSP body starts at the first symbol token; the controller incorrectly requires first-line indentation from its whole-line slice. Preserve the failed controller outcome.',
    'codegraph-requests1': 'Controller mapping failure: an empty renderer row after the final newline is incorrectly indexed as a physical source line. Preserve the failure; later controls mark this row outside source credit.',
    'codegraph-flask1': 'Controller mapping failure at a trailing empty renderer row. This early failure does not prove that the requested method body was delivered.',
    'codegraph-flask2': 'Source-coverage failure for make_response: every mapped visible source line matches, but the selected reply omits all 139 lines of Flask.make_response. A later process_response lookup is a different query and does not resolve this omission.',
}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


records = []
for folder in sorted(ROOT.glob('*')):
    path = folder / 'receipt.json'
    if not folder.is_dir() or not path.exists():
        continue
    receipt = json.loads(path.read_text())
    record = {
        'attempt': folder.name,
        'receipt_sha256': sha(path),
        'receipt': receipt,
        'diagnosis': CLASSIFICATION.get(folder.name, 'Successful bounded source-query control; no comparative benefit or adoption claim.'),
    }
    stderr = folder / 'mcp.stderr'
    if stderr.exists():
        record['retained_mcp_stderr'] = {'sha256': sha(stderr), 'text': stderr.read_text()}
    after = snapshot(folder / 'workspace')
    before = receipt['source_before']
    unchanged = all(after['files'].get(p) == digest for p, digest in before['files'].items())
    assert unchanged and after['head'] == before['head'], folder.name
    record['post_run_tracked_source_audit'] = {
        'performed_utc': datetime.now(timezone.utc).isoformat(),
        'head': after['head'], 'tracked_file_count': len(after['files']),
        'all_original_file_hashes_unchanged': unchanged,
        'git_status': after['git_status'],
        'scope': 'Read-only audit after the original terminal receipt; it does not replace that receipt or claim this audit was executed inside a failed original controller.',
    }
    records.append(record)

assert len(records) == 12
by_name = {r['attempt']: r['receipt'] for r in records}
tasks = json.loads((OUT / 'codegraph_matched_tasks_v1.json').read_text())
task_by_id = {t['task_id']: t for t in tasks['tasks']}
for case, row in SELECTED.items():
    task = task_by_id[row['task']]
    for arm in ('serena', 'codegraph'):
        result = by_name[row[arm]]
        assert result['status'] == 'passed'
        assert result['source_before']['head'] == task['source_commit']
        obs = result['source_observation']
        assert obs.get('exact_mapped_body_match') or (obs['all_visible_source_lines_exact'] and not obs['missing_symbol_body_lines'])

controllers = {}
for path in sorted(ROOT.glob('*.py')):
    if path.name == 'archive.py':
        continue
    digest = sha(path)
    controllers[digest] = {'filename': path.name, 'sha256': digest, 'source': path.read_text()}
for row in records:
    expected = row['receipt'].get('controller_sha256')
    if expected:
        assert expected in controllers, row['attempt']
    else:
        assert row['attempt'] == 'serena-pytest1'
        row['controller_file_retained_after_execution'] = 'serena_pytest.py'

diagnostics = {name: {'sha256': sha(ROOT / name), 'receipt': json.loads((ROOT / name).read_text())}
               for name in ['serena-help.json', 'serena-offline-diagnosis.json']}
ids = {r['receipt']['container_id'] for r in records}
ids |= {d['receipt']['container_id'] for d in diagnostics.values()}
engine = docker.from_env(timeout=60)
cleanup = []
try:
    for cid in sorted(ids):
        try:
            engine.containers.get(cid)
        except docker.errors.NotFound:
            cleanup.append({'container_id': cid, 'confirmed_absent': True})
        else:
            raise AssertionError('Owned container unexpectedly remains: ' + cid)
finally:
    engine.close()

preserved = {}
names = subprocess.check_output(['git', 'ls-tree', '-r', '--name-only', BASE, '--', 'docs/experiments'], cwd=CHECKOUT, text=True).splitlines()
for name in names:
    path = Path(name)
    if path.name.startswith('codegraph_') and path.suffix == '.json':
        old = subprocess.check_output(['git', 'show', BASE + ':' + name], cwd=CHECKOUT)
        assert old == (CHECKOUT / name).read_bytes(), name
        preserved[name] = sha(CHECKOUT / name)

references = []
for index, record in enumerate(records):
    path = OUT / f'codegraph_peer_source_admission_v1_{index:02d}.json'
    path.write_text(json.dumps(record, indent=2) + '\n')
    references.append({'attempt': record['attempt'], 'artifact': path.name, 'sha256': sha(path), 'status': record['receipt']['status'], 'diagnosis': record['diagnosis']})

artifact = {
    'schema_version': 1,
    'scope': 'Model-free peer startup/source-query admission with preinstalled/warm dependencies, separate from original frozen matched outcomes. No new benefit inference, rescore, model-improvement result or external-user claim.',
    'source_baseline': BASE,
    'source_selection': 'The three historically exposed matched-v1 repositories and their unchanged lookup tasks. Additional Flask.make_response controls remain separate.',
    'selected_lookup_controls': SELECTED,
    'attempt_counts': {'total': len(records), 'passed': sum(r['receipt']['status'] == 'passed' for r in records), 'failed': sum(r['receipt']['status'] == 'failed' for r in records)},
    'records': references,
    'controllers': controllers,
    'diagnostics': diagnostics,
    'owned_container_cleanup': cleanup,
    'prior_codegraph_json_files_unchanged': preserved,
    'model_inference_sessions': 0,
    'external_participants': 0,
    'open_gates': [
        'Complete source-checked prospective rubric and freeze a separate full benefit protocol before any new inference.',
        'Bind every arm to the same prospective runtime/source environment and complete measured install/cold/update preparation. These preinstalled controls are not a complete cold-start admission or timing comparison.',
        'Preserve the additional Codegraph Flask.make_response omission and bound source coverage; a nominal is_error:false does not establish a complete answer.',
        'Keep automatic optional-tool choice, native tools, original setup failures and unknown invoice charges visible.',
        'Whole-task correctness/time benefit and five consenting external users with seven-day voluntary reuse remain unproven.',
    ],
    'archive_implementation': {'sha256': sha(__file__), 'source': Path(__file__).read_text()},
}
target = OUT / 'codegraph_peer_source_admission_2026_10_28.json'
target.write_text(json.dumps(artifact, indent=2) + '\n')
print(json.dumps({'artifact': target.name, 'bytes': target.stat().st_size, 'counts': artifact['attempt_counts'], 'owned_containers_absent': len(cleanup), 'prior_codegraph_json_files_unchanged': len(preserved)}))
